const newPayload = {};
const data = msg.payload;
const points = data.metadata?.points;
if (!Array.isArray(points) || points.length < 2) {
    node.warn("Tripwire event missing endpoints");
    return null;
}

const dx = points[1][0] - points[0][0];
const dy = points[1][1] - points[0][1];
if (dx === 0 && dy === 0) {
    node.warn("Tripwire endpoints must differ");
    return null;
}
const horizontal = Math.abs(dx) >= Math.abs(dy);
const positiveDirection = horizontal ? (dx > 0 ? "down" : "up") : (dy > 0 ? "right" : "left");
const negativeDirection = horizontal ? (dx > 0 ? "up" : "down") : (dy > 0 ? "left" : "right");

newPayload.scene_name = data.scene_name;
newPayload.scene_id = data.scene_id;
newPayload.tripwire_name = data.tripwire_name;
newPayload.tripwire_id = data.tripwire_id;
newPayload.timestamp = data.timestamp;
newPayload.objects = (data.objects ?? []).map(function(object) {
    return {
        category: object.category,
        direction: object.direction === 1 ? positiveDirection : negativeDirection
    };
});

msg.payload = newPayload;
return msg;

