const now = Date.now();
const cutoff = now - 30_000;

Object.values(scenes).forEach(function (existingScene) {
	Object.values(existingScene.tripwires ?? {}).forEach(function (existingTripwire) {
		existingTripwire.events = (existingTripwire.events ?? []).filter(function (event) {
			return event.date >= cutoff;
		});
	});
});

const scene = scenes[data.scene_id] ?? {};

