const timer = setInterval(function () {
    const scenes = flow.get('scenes') || {};
    const cutoff = Date.now() - 30_000;
    let changed = false;
    Object.values(scenes).forEach(function (scene) {
        Object.values(scene.tripwires ?? {}).forEach(function (tripwire) {
            const events = tripwire.events ?? [];
            tripwire.events = events.filter(function (event) {
                return event.date >= cutoff;
            });
            changed = changed || tripwire.events.length !== events.length;
        });
    });
    if (changed) {
        flow.set('scenes', scenes);
        node.send({});
    }
}, 1000);
context.set('tripwirePruneTimer', timer);

